// TH18 v1.00a Stage 2 MainSub06 + async MainSub06b
// st02.ecl.txt:1236-1265 (spawn schedule), 131-221 (GirlA01/GirlA01_at), 511-551 (red/blue wrappers)
const TIME_LIMIT: int = 1100;
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480; // source etSprite type 8

// Shell holder at (0,0): no body, no hurtbox, invulnerable; owns the phase clock.
async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    set_hurtbox(0fx);
    set_hitbox(0fx);
    phase_begin(0, none, TIME_LIMIT, 0);
    loop { wait(1); }
}

// GirlA01_at S:152-191. The EX type 2 / a=1 ANIM retreat is 4*speed opposite the shot
// direction; aim is taken from the emitter before that retreat.
async sub girl_a01_at(rank: int) {
    wait(rand(60)); // source wait($RAND % 60)
    var speed: fx = 1.5fx;
    if rank == 2 { speed = 2.6fx; }
    if rank == 3 { speed = 4fx; }
    var count: int = 1;
    if rank == 2 { count = 8; }
    if rank == 3 { count = 100; }
    var gap: int = 30;
    if rank == 3 { gap = 20; }
    for i in 0..count {
        // Easy has the 1/3 fire gate; all higher ranks fire every slot.
        if rank >= 1 || rand(3) == 0 {
            var a: angle = atan2($player_y - $self_y, $player_x - $self_x);
            var back: fx = 4fx * speed;
            _ = fire(TH18_RICE, 6,
                $self_x - back * cos(a), $self_y - back * sin(a),
                speed, a, none, none);
        }
        if i < count - 1 { wait(gap); }
    }
}

// GirlA01 S:131-150 with the GirlRedA01/GirlBlueA01 wrappers' spawn parameters.
async sub girl_a01(rank: int) {
    set_hurtbox(12fx); // source setHurtbox(24,24), circular damage takes half
    set_hitbox(8fx);   // source setHitbox(16,16)
    set_invuln(65535);
    var head: angle = atan2(300fx - $self_y, 0fx - $self_x); // getAngle(...,0,300)
    move_vel(0, head, 3.3fx, EASE_LINEAR);
    spawn girl_a01_at(rank);
    wait(60);
    move_speed(60, 0.2fx, EASE_QUAD_IN);                         // moveSpeedTime(60,1,0.2)
    var back_angle: angle = atan2($player_y - $self_y, $player_x - $self_x)
        + 180deg + (rand(3641) as angle);                         // +pi + RANDF2*20deg
    move_angle(60, back_angle, EASE_QUAD_IN);                     // moveAngleTime(60,1,...)
    wait(60);
    move_speed(120, 1.8fx, EASE_QUAD_IN);                         // moveSpeedTime(120,1,1.8)
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    wait(OPENING_BUFFER);
    var rank: int = global(GVAR_RANK);
    // MainSub06 and its async MainSub06b interleaved in source order:
    // red left, blue right +1 frame; blue left +15, red right +16; period 30.
    for round in 0..10 {
        var u: fx = ((rand(65536) - 32768) as fx) * 0.000030517578125fx + 0.5fx;
        _ = spawn_enemy(-224fx + u * 64fx, -48fx, 160, 0, 0, 0, girl_a01(rank));
        wait(1);
        u = ((rand(65536) - 32768) as fx) * 0.000030517578125fx + 0.5fx;
        _ = spawn_enemy(224fx + u * 64fx, -48fx, 160, 0, 0, 0, girl_a01(rank));
        wait(14);
        u = ((rand(65536) - 32768) as fx) * 0.000030517578125fx + 0.5fx;
        _ = spawn_enemy(-224fx + u * 64fx, -48fx, 160, 0, 0, 0, girl_a01(rank));
        wait(1);
        u = ((rand(65536) - 32768) as fx) * 0.000030517578125fx + 0.5fx;
        _ = spawn_enemy(224fx + u * 64fx, -48fx, 160, 0, 0, 0, girl_a01(rank));
        wait(14);
    }
    loop { wait(60); }
}
